package com.bank.approvals.service;

import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// Does the ledger contain any contiguous block that is a permutation of the required set?
public class ApprovalLedgerScanner {
    private static final Logger log = Logger.getLogger(ApprovalLedgerScanner.class.getName());

    public boolean containsCompleteApprovalSet(String ledger, String required) {
        if (ledger == null || required == null || ledger.length() < required.length()
                || required.isEmpty()) {
            return false;
        }
        Map<Character, Integer> need = new HashMap<>();
        for (char c : required.toCharArray()) {
            need.merge(c, 1, Integer::sum);
        }
        int requiredDistinct = need.size();
        Map<Character, Integer> window = new HashMap<>();
        int matches = 0;
        int w = required.length();

        for (int right = 0; right < ledger.length(); right++) {
            char in = ledger.charAt(right);
            if (need.containsKey(in)) {
                int cnt = window.merge(in, 1, Integer::sum);
                if (cnt == need.get(in)) matches++;
                else if (cnt == need.get(in) + 1) matches--;
            }
            // Remove the element leaving the fixed-size window.
            if (right >= w) {
                char out = ledger.charAt(right - w);
                if (need.containsKey(out)) {
                    int cnt = window.merge(out, -1, Integer::sum);
                    if (cnt == need.get(out)) matches++;
                    else if (cnt == need.get(out) - 1) matches--;
                }
            }
            if (matches == requiredDistinct) {
                final int start = right - w + 1;
                log.fine(() -> "Complete approval set found at block start " + start);
                log.info(() -> "Ledger '" + ledger + "' contains required set '"
                        + required + "' = true");
                return true;
            }
        }
        log.info(() -> "Ledger '" + ledger + "' contains required set '" + required + "' = false");
        return false;
    }
}
